import http from 'node:http';import {readFile} from 'node:fs/promises';import path from 'node:path';const root=process.cwd();http.createServer(async(req,res)=>{try{const name=decodeURIComponent(new URL(req.url,'http://localhost').pathname),file=path.resolve(root,'.'+(name==='/'?'/index.html':name));if(!file.startsWith(root+path.sep))throw Error('path');const data=await readFile(file);res.setHeader('Content-Type',file.endsWith('.html')?'text/html':file.endsWith('.json')?'application/json':file.endsWith('.glb')?'model/gltf-binary':'text/javascript');res.end(data);}catch{res.writeHead(404);res.end('Not found');}}).listen(Number(process.env.PORT||8813),'127.0.0.1');